/**
 * Simple replacement for JUnit 5's {@code assertDoesNotThrow} to avoid adding a JUnit 5
 * dependency. It executes the supplied {@code ThrowingRunnable} and fails the test if
 * any {@link Throwable} is thrown.
 */
private static void assertDoesNotThrow(ThrowingRunnable runnable, String message) {
    try {
        runnable.run();
    } catch (Throwable t) {
        fail(message + ": " + t);
    }
}

