      () -> reader.peek());
}

/** Verifies the exact error message produced for a JSON string ending with a slash. */
@Test
public void testStringEndingInSlash_exceptionMessage() {
  JsonReader reader = new JsonReader(reader("/"));
  reader.setStrictness(Strictness.LENIENT);
  MalformedJsonException e = captureMalformedJsonException(reader);
  assertThat(e)
      .hasMessageThat()
      .isEqualTo(
          "Expected value at line 1 column 1 path $\n"
              + "See https://github.com/google/gson/blob/main/Troubleshooting.md#malformed-json");
}

/** Helper that runs `reader.peek()` and returns the resulting {@link MalformedJsonException}. */
private static MalformedJsonException captureMalformedJsonException(JsonReader reader) {
  try {
    reader.peek();
    // If no exception is thrown, this is an unexpected condition.
    throw new AssertionError("Expected MalformedJsonException was not thrown");
  } catch (MalformedJsonException ex) {
    return ex;
  } catch (IOException ex) {
    // Wrap checked exceptions that are not part of the test expectation.
    throw new RuntimeException(ex);
  }
}

